#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys
import base64

_ENCODED = ""

def _decode_payload():
    try:
        data = _ENCODED.encode('ascii')

        data = base64.b64decode(data)

        key = b"MRSH_SRC_2024"
        data = bytes(data[i] ^ key[(i*7+3) % len(key)] for i in range(len(data)))

        data = data[::-1]

        data = base64.b64decode(data)

        data = bytes(data[i] ^ key[i % len(key)] for i in range(len(data)))

        data = base64.b64decode(data)
        source = data.decode('utf-8')

        return source
    except Exception as e:
        sys.stderr.write("Decode error: " + str(e) + chr(10))
        raise

def _run():
    try:
        source = _decode_payload()
        ns = {'__name__': '__main__', '__file__': getattr(sys.modules['__main__'], '__file__', '<protected>')}
        exec(compile(source, '<protected>', 'exec'), ns)
    except SystemExit:
        raise
    except Exception as e:
        import traceback
        sys.stderr.write("Execution error: " + str(e) + chr(10))
        traceback.print_exc()
        raise

if __name__ == "__main__":
    try:
        _run()
    except SystemExit as e:
        sys.exit(e.code)
    except (KeyboardInterrupt, EOFError):
        pass
    except Exception:
        sys.exit(1)
